import pandas as pd
from io import StringIO
import json
df = pd.read_csv(StringIO(csv_content))
issues = {
    "schema_drift": [],
    "type_errors": [],
    "missing_values": [],
    "duplicates": [],
    "outliers": []
}
expected_cols = ["date", "product", "revenue", "quantity"]
for col in expected_cols:
    if col not in df.columns:
        issues["schema_drift"].append(f"Missing column: {col}")
if "revenue" in df.columns and not pd.api.types.is_numeric_dtype(df["revenue"]):
    issues["type_errors"].append("revenue column is not numeric")
for col in df.columns:
    if df[col].isnull().any():
        issues["missing_values"].append(col)
if df.duplicated().any():
    issues["duplicates"].append(df.duplicated().sum())
if "revenue" in df.columns and pd.api.types.is_numeric_dtype(df["revenue"]):
    Q1 = df["revenue"].quantile(0.25)
    Q3 = df["revenue"].quantile(0.75)
    IQR = Q3 - Q1
    outlier_count = ((df["revenue"] < (Q1 - 1.5 * IQR)) | (df["revenue"] > (Q3 + 1.5 * IQR))).sum()
    if outlier_count > 0:
        issues["outliers"].append(outlier_count)
json.dumps(issues)

import pandas as pd
from io import StringIO
import json
df = pd.read_csv(StringIO(csv_content))
issues = json.loads(detected_issues)
if any("revenue column is not numeric" in err for err in issues["type_errors"]):
    df["revenue"] = pd.to_numeric(df["revenue"], errors="coerce")
for col in issues["missing_values"]:
    if pd.api.types.is_numeric_dtype(df[col]):
        df[col].fillna(df[col].median(), inplace=True)
    else:
        df[col].fillna(df[col].mode()[0], inplace=True)
if issues["duplicates"]:
    df.drop_duplicates(inplace=True)
if "revenue" in df.columns and pd.api.types.is_numeric_dtype(df["revenue"]):
    Q1 = df["revenue"].quantile(0.25)
    Q3 = df["revenue"].quantile(0.75)
    IQR = Q3 - Q1
    df["revenue"] = df["revenue"].clip(lower=Q1 - 1.5 * IQR, upper=Q3 + 1.5 * IQR)
df.to_json()

